+// Move directly between registers.
+instruct moveD2L_reg_reg(iRegLdst dst, regD src) %{
+  match(Set dst (MoveD2L src));
+  ins_cost(DEFAULT_COST);
+  format %{ "MFFPRD  $src, $dst \t// MoveD2L" %}
